WITH lines AS (SELECT id, pos, item.product_id, item.qty, item.promo FROM carts LATERAL VIEW OUTER POSEXPLODE(items) x AS pos, item) SELECT promo, SUM(CASE WHEN promo = 'WELCOME5' THEN pos ELSE 0 END) AS welcome5_pos, ROUND(AVG(product_id), 2) AS avg_product_id, COUNT(CASE WHEN promo = 'WELCOME5' THEN 1 END) AS welcome5_count FROM lines GROUP BY 1 ORDER BY welcome5_pos NULLS LAST;
